cd /tmp/claude-1000/-home-jess-Documents-primary-juvenile-meta-analysis/f33aec72-33ab-4de0-94cc-8382a00dec58/scratchpad; cat > kubiak.py <<'E'
import re,random,sys
from lib import *
STEM='Kubiak Cunn 2009'
L=open(ROOT+f'data/papers_test/md_agents/{STEM}.md').read().split('\n')
SRC='Kubiak, P. J. (2009). Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia, 11(1), 131-165.'
SITES=['Lane Cove River valley','Narrabeen Lagoon catchment area']
SHARED=' / '.join(SITES)
def dash(s): return s.replace('–','-').replace('—','-').replace('‑','-')
page=None;rows=[]
for i,l in enumerate(L):
    m=re.match(r'^(\d+) Cunninghamia 11\(1\)',l) or re.search(r'Cunninghamia 11\(1\): 2009 — Kubiak.*? (\d+)$',l)
    if m: page=m.group(1)
    if i>=475 and l.startswith('|') and not l.startswith('| Family') and not l.startswith('|---'):
        c=[x.strip() for x in l.strip().strip('|').split('|')]
        assert len(c)==12
        rows.append((i+1,page,c,l))
CORE=re.compile(r'^(c\.\s?)?\??(\d+(?:\.\d+)?)(?:-(\d+(?:\.\d+)?))?(\+)?\s?(w|y)?\??(.*)$')
def fmt(x): return f'{x:.3f}'.rstrip('0').rstrip('.')
def legend(raw):
    t=[]
    if '(shd)' in raw: t.append('(shd) = shedding seed or spores')
    if re.search(r'grn|green',raw): t.append('grn = green fruit')
    if re.search(r'-ri\b',raw) or '(ripe)' in raw: t.append('ri = ripe fruit')
    if 'imm' in raw: t.append('imm = immature fruit')
    if '(1)' in raw: t.append('(1) = one plant')
    if 'buds' in raw: t.append('buds = flowers in bud')
    if 'm.i.f' in raw: t.append('m.i.f = moderate intensity fire')
    if '**' in raw: t.append('bold = sizable proportion of population flowering')
    return t
def parse(raw):
    """-> (value, unit, extra) ; value None if not parseable"""
    s=dash(raw).replace('**','').strip()
    first=s.split(',')[0].strip()
    m=CORE.match(first)
    if not m: return None
    c,a,b,plus,unit,rest=m.groups()
    if unit is None: return ('NOUNIT',None,None)
    unit='weeks' if unit=='w' else 'years'
    if plus: val='>'+a
    elif b: val=a+'-'+b
    else: val=a
    return (val,unit,(a,b,plus))
def toyears(v,unit):
    if unit=='years': return v,None
    def cv(x): return fmt(float(x)/52)
    if v.startswith('>'): return '>'+cv(v[1:]),v[1:]
    if '-' in v: x,y=v.split('-'); return cv(x)+'-'+cv(y),v
    return cv(v),v
def build(c,page_,line):
    fam,sp,peak,lcr,nl,seed,flR,flS,frR,frS,pjp,sjp=c
    name_notes=[]
    s=dash(sp)
    exotic=s.startswith('*') and not s.startswith('(*')
    uncertain_exotic=s.startswith('(*?)')
    s=s.lstrip('*'); s=s.replace('(*?)','')
    orig=s
    s=re.sub(r'\s*\((s\.lat\.|s\.str\.)\)','',s); s=re.sub(r'\s*\(syn\. [^)]*\)','',s)
    s=s.replace('“','').replace('”','').replace('?','').strip()
    s=re.sub(r'\s+',' ',s)
    if s!=orig or uncertain_exotic or exotic and False: name_notes.append(f"name printed as '{('(*?)' if uncertain_exotic else '')+orig}'")
    toks=s.split(' ')
    g=toks[0]; rest=toks[1:]
    sub=''
    for k,t in enumerate(rest):
        if t in('subsp.','var.','cv.','f.') and k>0:
            sub=' '.join(rest[k:]); rest=rest[:k]; break
    spc=' '.join(rest)
    base=blank(); base['Genus']=g;base['Species']=spc;base['subsp']=sub;base['scientific_name']=f'{g} {spc}'
    base['Family']=fam[0].upper()+fam[1:]
    if exotic: base['native_status']='exotic'
    # fire response per site
    codes={}; fnotes={}
    for site,cell in zip(SITES,(lcr,nl)):
        t=dash(cell).replace(' ','')
        m=re.match(r'^(\??p?[KkRr](?:[/;]\??[KkRr])?)(.*)$',t)
        if m:
            codes[site]=m.group(1)
            if m.group(2) or len(cell)>8: fnotes[site]=f"fire response printed as '{dash(cell)}'"
        elif cell: fnotes[site]=f"fire response cell text: '{dash(cell)}'"
    shared_notes=[]  # near matches
    timecols={}; tnotes=[]
    def conv_col(col,val,unit,label,raw):
        v,orig=toyears(val,unit)
        timecols[col]=v
        if orig is not None: tnotes.append(f"{col} converted from {orig} weeks")
        if raw_has_extra(raw): tnotes.append(f"{label} printed '{dash(raw)}'"+legend_s(raw))
    def raw_has_extra(raw):
        return not re.fullmatch(r'\d+(\.\d+)?(-\d+(\.\d+)?)?[wy]',dash(raw).strip())
    def legend_s(raw):
        l=legend(raw); return ' ('+'; '.join(l)+')' if l else ''
    def handle(raw,col,label,fixed_years):
        if not raw: return
        if '<u>' in raw: return 'u'
        if len(re.sub(r'[^A-Za-z]','',re.sub(r'(shd|grn|imm|ri|buds|green|ripe|adv|m\.i\.f|u|w|y|c|few|fruit|small|pop)\b','',dash(raw))))>2 and not raw.startswith('Resprouted') and not raw.startswith('At least') and not raw.startswith('Less than'):
            tnotes.append(f"{label} cell text: '{dash(raw)}'"); return
        if raw.startswith('At least'):
            val,unit='>'+re.search(r'\d+',raw).group(),'years'
        elif raw.startswith('Less than'):
            val,unit='<'+re.search(r'\d+',raw).group(),'years'
        elif raw.startswith('Resprouted'):
            n=re.search(r'(\d+)w',raw).group(1); val,unit=n,'weeks'
        else:
            p=parse(raw)
            if p is None: tnotes.append(f"{label} printed '{dash(raw)}'"); return
            if p[0]=='NOUNIT': tnotes.append(f"{label} printed '{dash(raw)}' (unit not stated)"); return
            val,unit=p[0],p[1]
        if fixed_years: conv_col(col,val,unit,label,raw)
        else:
            timecols[col]=val; timecols['_unit']=unit
            if raw_has_extra(raw) or raw.startswith(('At least','Less than')): tnotes.append(f"{label} printed '{dash(raw)}'"+legend_s(raw))
    # flowering
    ufl=[]
    for cell,col,label in ((flS,'Age at first flower production from seed_repr3','first flowering (seed)'),(flR,'Time to first flower production resprout_repr3a','first flowering (resprout)')):
        r=handle(cell,col,label,True)
        if r=='u': ufl.append(cell)
    if ufl: shared_notes.append(f"first flowering bridges resprout and seed columns (underlined, source unclear): '{dash(ufl[0]).replace('<u>','').replace('</u>','')}'"+legend_s(ufl[0]))
    handle(pjp,'primary_juvenile_period','primary juvenile period',True)
    handle(sjp,'secondary_juvenile_period','secondary juvenile period',False)
    ufr=[]
    for cell,label in ((frS,'first fruiting (seed)'),(frR,'first fruiting (resprout)')):
        if not cell: continue
        if '<u>' in cell: ufr.append(cell); continue
        shared_notes.append(f"{label} (not a flowering measure): '{dash(cell)}'"+legend_s(cell))
    if ufr: shared_notes.append(f"first fruiting bridges resprout and seed columns (underlined; not a flowering measure): '{dash(ufr[0]).replace('<u>','').replace('</u>','')}'"+legend_s(ufr[0]))
    if seed: shared_notes.append(f"seedlings first observed: '{dash(seed)}'")
    if peak: shared_notes.append(f"post-fire flowering or fruiting peak (not a flowering-time measure): '{dash(peak)}'")
    tc={k:v for k,v in timecols.items() if k!='_unit'}
    out=[]
    def mk(site,loc_all,notes):
        r=dict(base)
        r['Fire_type']='wildfire';r['Fire_season_categorical']='Summer';r['Fire_severity_categorical']='High'
        r['Source']=SRC;r['File_name']=STEM
        if site: 
            r['Location_name']=site;r['Latitude']='-33.75';r['Longitude']='151.0833'
            if site in codes:
                cd=codes[site]
                r['fire_response categorical_surv1']={'R':'resprouter','K':'obligate'}.get(cd,cd)
        else: r['Location_name']=SHARED
        n=[f'Appendix 1, p. {page_}']+name_notes+notes
        n.append('Fire_season_categorical derived from January 1994 fires; Fire_severity_categorical from fires generally of apparently high intensity')
        r['Notes']='; '.join(n)
        return r
    def addtimes(r):
        for k,v in tc.items(): r[k]=v
        if 'secondary_juvenile_period' in tc: r['Time_unit']=timecols['_unit']
    rec=[s_ for s_ in SITES if s_ in codes]
    if len(rec)==1:
        r=mk(rec[0],False,[fnotes[rec[0]]] if rec[0] in fnotes else []); 
        r['Notes']=r['Notes']  # fallthrough
        other=[s_ for s_ in SITES if s_ not in codes and s_ in fnotes]
        addtimes(r); r['Notes']+= '; '+'; '.join(tnotes+shared_notes+[f"{o} cell: {fnotes[o]}" for o in other]) if (tnotes or shared_notes or other) else ''
        out.append(r)
    elif len(rec)==2:
        for s_ in rec:
            r=mk(s_,False,[fnotes[s_]] if s_ in fnotes else [])
            out.append(r)
        if tc:
            r=mk(None,True,tnotes+shared_notes); addtimes(r); out.append(r)
        else:
            for r in out:
                if tnotes or shared_notes: r['Notes']+='; '+'; '.join(tnotes+shared_notes)
    else:
        if tc:
            r=mk(None,True,tnotes+shared_notes+list(fnotes.values())); addtimes(r); out.append(r)
    # drop rows lacking fire response and time values
    final=[r for r in out if r['fire_response categorical_surv1'] or any(r[k] for k in ('Age at first flower production from seed_repr3','Time to first flower production resprout_repr3a','primary_juvenile_period','secondary_juvenile_period'))]
    return final,len(out)-len(final)
allout=[];src=[];dropped=0;nosp=[]
for line,pg,c,raw in rows:
    o,d=build(c,pg,line)
    dropped+=d
    if not o: nosp.append(c[1])
    for r in o: allout.append(r); src.append(raw)
print('species',len(rows),'rows',len(allout),'dropped',dropped,'species w/o row',nosp)
random.seed(7)
for i in random.sample(range(len(allout)),3):
    r=allout[i]; print(src[i]); print({k:v for k,v in r.items() if v and k not in('Source','File_name')})
if len(sys.argv)>1 and sys.argv[1]=='write': append(allout)
E
